import { Difficulty, QuestionItem } from './types';

// Helper for Game 5: ¡Compra en 10 segundos!
function mkG5(level: Difficulty, rows: [string, string, string, string[]][]): QuestionItem[] {
  return rows.map(([prompt, promptHy, answer, altAnswers], idx) => ({
    id: `g5_${level}_${idx + 1}`,
    gameId: 'compra_10s',
    level,
    prompt,
    promptHy,
    answer,
    altAnswers,
    answerDetail: 'Se aceptan otras frases naturales y gramaticalmente correctas.',
  }));
}

// Helper for Game 6: ¡Tres pistas, una palabra!
function mkG6(
  level: Difficulty,
  rows: [[string, string, string], [string, string, string], string, string][]
): QuestionItem[] {
  return rows.map(([clues, cluesHy, answer, hyWord], idx) => ({
    id: `g6_${level}_${idx + 1}`,
    gameId: 'tres_pistas',
    level,
    prompt: clues[0],
    clues,
    cluesHy,
    answer,
    answerDetail: `Հայերեն՝ ${hyWord}`,
  }));
}

// Helper for Game 7: ¡Dilo de otra manera!
function mkG7(level: Difficulty, rows: [string, string, string, string[]][]): QuestionItem[] {
  return rows.map(([prompt, promptHy, answer, altAnswers], idx) => ({
    id: `g7_${level}_${idx + 1}`,
    gameId: 'dilo_otra_manera',
    level,
    prompt,
    promptHy,
    answer,
    altAnswers,
    answerDetail: 'También valen otros sinónimos o paráfrasis correctas.',
  }));
}

// Helper for Game 8: ¡Elige el tiempo!
function mkG8(
  level: Difficulty,
  rows: [string, string, [string, string, string, string], 'A' | 'B' | 'C' | 'D', string][]
): QuestionItem[] {
  return rows.map(([prompt, promptHy, opts, correctOption, tenseName], idx) => {
    const labels: ('A' | 'B' | 'C' | 'D')[] = ['A', 'B', 'C', 'D'];
    const options = labels.map((label, i) => ({ label, text: opts[i] }));
    const correctObj = options.find((o) => o.label === correctOption)!;
    return {
      id: `g8_${level}_${idx + 1}`,
      gameId: 'elige_tiempo',
      level,
      prompt,
      promptHy,
      options,
      correctOption,
      tenseName,
      answer: `${correctOption}. ${correctObj.text}`,
      answerDetail: `Tiempo verbal: ${tenseName}`,
    };
  });
}

